def match_transitive_degree10(observed):
    """Among the 45 transitive degree-10 groups, find those whose element-weighted
    cycle-type distribution is compatible with the observed census. Compatibility =
    same set of cycle types with nonzero density (up to census noise on rare types)
    and 10-cycles present (the diagnostic feature). Returns list of (tn, |G|, struct)."""
    from sage.groups.perm_gps.permgroup_named import TransitiveGroup

    def cyc_of(g):
        ts = list(g.cycle_tuples()); lens = sorted([len(t) for t in ts], reverse=True)
        nf = _sage_const_10  - sum(lens); return tuple(lens + [_sage_const_1 ] * nf)
    obs_types = set(observed.keys())
    obs_has10 = (_sage_const_10 ,) in observed
    matches = []
    for i in range(_sage_const_1 , _sage_const_46 ):
        T = TransitiveGroup(_sage_const_10 , i)
        gord = T.order()
        dist = Counter()
        for g in T:
            dist[cyc_of(g)] += _sage_const_1 
        types = set(dist.keys())
        orders = sorted(set(int(x.order()) for x in T.conjugacy_classes_representatives()))
        # require: all element orders divide 10 (the census shows only lens | 10)
        if not all(o in (_sage_const_1 , _sage_const_2 , _sage_const_5 , _sage_const_10 ) for o in orders):
            continue
        # require: has 10-cycle iff observed has it
        has10 = any(o == _sage_const_10  for o in orders)
        if has10 != obs_has10:
            continue
        # require: predicted cycle-type set matches observed set (the diagnostic step)
        if types != obs_types:
            continue
        try:
            nm = T.structure_description()
        except Exception:
            nm = ""
        matches.append((i, gord, nm, dist))
    return matches


